{
  "dimensions": {
    "句式": {
      "description": "长句通过并列与嵌套混合堆积，如'紧身修女服将她们除脸部外全都遮盖的严严实实，但犯规肉感的女体散发的雌性诱惑力，在这层薄薄衣衫的包裹中，仿佛一用力就可捏出其中淫靡肥润色欲爆表的雌肉'（约70字），使用'但'转折并列，后接'仿佛'比喻嵌套。短句用于动作或心理突转，如'特鲁现在男孩的脚掌还不如辛西娅的手大''啵~'，简洁有力。'的'字密度极高，平均每句出现2-3次，如'肥硕花白奶子''艳红的乳头高高翘起'，形成浓郁修饰。句号控制叙述节奏，逗号用于长句内部分割，如'那皮带从爆乳的腻白乳肉下环绕而过，紧绷束缚在脖颈上项圈中，肥硕花白奶子，在黑色皮带的固定中'，逗号使描述层层递进。",
      "vocabularyList": ["等等的遮盖", "丰腴身材", "性感诱惑力", "薄薄衣衫", "肥硕花白奶子", "艳红的乳头", "高高翘起", "层层叠叠", "肥厚熟靡", "淫荡蜜穴"],
      "writingRules": ["使用'但''却'等转折词连接并列长句，制造反差", "短句用于动作收尾或拟声词，增强节奏感", "高频使用'的'字堆叠形容词，每句至少2-3个", "逗号分割长句内部并列成分，句号结束完整画面"]
    },
    "词汇": {
      "description": "独特的复合形容词公式为'情感形容词+身体部位+状态'，如'靡情雌肉'(靡情+雌肉)、'腻白乳肉'(腻白+乳肉)、'肥厚熟靡'(肥厚+熟靡)。高频修饰词包括'肥'(肥硕、肥腻)、'熟'(熟透、淫熟)、'淫'(淫靡、淫熟)、'靡'(靡艳、熟靡)、'腻'(腻白、软腻)、'巨'(巨乳)、'爆'(爆乳、爆臀)。文白夹杂风格：书面细腻描写如'紫红相间艳情饱满的妆容''魅意横流情波四射的风骚容颜'，粗俗器官词如'鸡巴''小穴''菊花'，形成高雅与低俗的强烈碰撞。",
      "vocabularyList": ["靡情雌肉", "腻白乳肉", "肥厚熟靡", "淫熟", "靡艳", "软腻", "爆乳", "爆臀", "巨尻", "肥腻淫舌", "厚靡软舌", "淫荡蜜穴", "骚贱巨尻母猪", "豆丁大小鸡鸡", "熟透雌肉"],
      "writingRules": ["创造复合词：情感形容词+身体部位+状态，如'淫熟美肉'", "高频使用'肥/熟/淫/靡/腻/巨/爆'七字，每段至少出现3次", "先写书面细腻环境或妆容，再突然插入粗俗器官词制造张力"]
    },
    "身体描写": {
      "description": "身体描写顺序从上到下：先整体（'巨乳肥臀的丰腴身材'），再局部特写（爆臀、巨乳、阴部）。'肥而不垂'的熟女美学体现于'肥硕花白奶子，在黑色皮带的固定中，从腋下层层叠叠码在一堆'，强调肥硕但不下垂。局部特写的放大镜技法：'包皮和龟头紧密贴合再一起的鸡鸡''舌根底部的舌下腺''阴毛从阴阜长到腹部底端'，对微结构极限描写。皮带的SM功能化：'只有几根皮带捆绑住身体''从爆乳的腻白乳肉下环绕而过，紧绷束缚在脖颈上项圈中'，皮带既束缚又塑形，强调肉感与压制。",
      "vocabularyList": ["巨乳肥臀", "丰腴身材", "爆臀", "巨乳", "腻白乳肉", "肥硕花白奶子", "层层叠叠", "艳红乳头", "巨大乳晕", "肥厚熟靡蜜穴", "阴毛乱卷", "褐色阴毛", "皮扣项圈", "皮带"],
      "writingRules": ["从整体轮廓到局部细节，按头-胸-腹-阴的顺序", "强调肥硕但不下垂，用'层层叠叠码在一堆'或'皮带固定'实现", "对包皮、舌下腺、阴毛等微结构放大描写，用'似有雷达声波'等比喻", "将皮带赋予双重功能：束缚肉体+塑造形状，如'提挤的更为凸起显著'"]
    },
    "感官": {
      "description": "口腔内部微观视角：'舌头卷曲露出舌根底部的舌下腺，多年培养修炼口腔里分泌粘稠量大的唾液，从管口处喷射出两道水线'，精细到唾液腺管口。触觉描写风格以'软腻''湿滑''温暖''粘稠'为主，如'温暖湿滑的软肉天堂''唇肉的软腻回应着践踏'，强调包裹感和柔软。体液描写风格：淫水、唾液、奶汁大量出现，如'潺潺淫水已经湿润了阴唇周遭''唾液的粘稠''充盈饱满乳汁的巨乳'，以'量多''粘稠''喷射'为特征。",
      "vocabularyList": ["舌下腺", "唾液管", "水线", "包皮缝", "唇肉", "软腻", "湿滑", "温暖", "粘稠", "淫水", "唾液的粘稠", "乳汁", "喷射", "尿垢", "苦涩腥骚"],
      "writingRules": ["选择口腔内最微小结构（舌下腺、包皮缝）进行特写", "触觉用'软腻/粘稠/湿滑'三词，每段至少出现一次", "体液描写强调'量多'和'喷射'，用动词'涌入、飙入、暴风吸入'"]
    },
    "叙事视角": {
      "description": "第三人称全知视角，但大量使用自由间接引语进入人物内心，如'这是对做了二十多年总管辛西娅的一场考验'（辛西娅的心理）、'那怕是以前脱敏角质化的龟头，现在正式初生如破处般'（特鲁的感受）。视角在辛西娅和特鲁之间自由切换，如'辛西娅那为服侍特鲁而锻炼出的绝世淫舌'（辛西娅视角），'特鲁只觉脚掌陷入到温暖湿滑的软肉天堂'（特鲁视角）。全知叙述者直接评论，如'但服侍教皇的性欲就是幸福神教最伟大高尚的目标'，揭示价值体系。",
      "vocabularyList": ["考验", "脱敏角质化", "初生如破处", "绝世淫舌", "幸福神教", "伟大高尚的目标"],
      "writingRules": ["使用'这是……的考验'等句式引入人物心理", "在动作描写后立即接'只觉''感觉'等词接入自由间接引语", "全知叙述者随时插入价值判断句，如'就是……伟大高尚的目标'"]
    },
    "权力反转": {
      "description": "教皇变小后的身体弱势vs身份权威：'变小成男孩是特鲁从未有过的新奇体验'，身体如'豆丁大小的鸡鸡'，但身份仍是教皇。'考验'框架的叙事功能：'这是对做了二十多年总管辛西娅的一场考验'，将性服侍转化为神圣考验。跪拜服侍中的权力确认：辛西娅'俯身拿起脚掌行吻礼'，并用'骚贱巨尻母猪'自称，通过自我贬低强化教皇权威。即使身体弱小，教皇仍能'踩踏'辛西娅的唇肉，权力通过行为确认。",
      "vocabularyList": ["变小", "豆丁大小", "考验", "行吻礼", "骚贱巨尻母猪", "踩踏", "践踏"],
      "writingRules": ["用身体对比突出反差：男孩vs权威，豆丁鸡鸡vs巨乳肥臀", "将性行为包装为'考验'，赋予神圣意义", "通过服侍动作中的低位姿势（吻脚、跪坐）和自称侮辱语确认权力"]
    },
    "羞辱公式": {
      "description": "自我羞辱语的风格为'骚贱+身体部位+动物'，如'骚贱巨尻母猪'，'骚贱'表低贱，'巨尻'强调性特征，'母猪'动物化。服侍=荣耀设定：'服侍教皇的性欲就是幸福神教最伟大高尚的目标''您最忠实的骚贱巨尻母猪，一定会让您得到最舒适巅峰的快乐'，将羞辱性自称与忠诚荣耀挂钩。其他修女的服侍也以'姐妹们大家上'为号令，集体性服侍被正常化。求辱语如'您就安心享受吧'，将接受服侍视为恩赐。",
      "vocabularyList": ["骚贱巨尻母猪", "最忠实", "最伟大高尚的目标", "最舒适巅峰的快乐", "姐妹们大家上"],
      "writingRules": ["创造自称公式：'骚贱'+身体特征+'母猪/母狗'等动物", "将羞辱语放在'忠诚'语境中，如'您最忠实的……'", "用'享受''快乐''伟大高尚'等词（实际是性服务）进行价值翻正"]
    },
    "拟声词": {
      "description": "拟声词位置集中在口交、吸吮动作后，如'呼呼嗯嗯，咕啾~'（吮吸脚掌），'啵~'（吐出鸡巴）。密度极低，全篇仅出现3次，但每次使用都标志动作转折点：'咕啾'表持续吮吸，'啵'表分离。模式为波浪线~增强淫靡感，且拟声词均独立成短句或段落，加~营造拖长音效。另有一处'砸吧'表吸奶声，但未加~。",
      "vocabularyList": ["呼呼嗯嗯", "咕啾~", "啵~", "砸吧"],
      "writingRules": ["拟声词密度控制在每千字2-3次，仅用于高潮动作转折", "口交时用'咕啾~'，分离时用'啵~'，加~表示延长", "拟声词独立成行或句，前后无标点干扰"]
    },
    "造词模式": {
      "description": "作者通过组合已有词汇创造新复合词：形容词+名词（'淫熟'=淫荡+成熟），名词+名词（'雌肉'=雌性+肉），或三者叠加（'靡情雌肉'=靡情+雌肉）。来源领域主要为情色文学常用语：'靡''淫''熟'来自古典情色；'肥''巨''爆'来自现代成人描述；'雌肉''美肉'来自动物化。另将专业解剖词引入：'舌下腺''包皮缝'，增加科学感。造词公式：(情感/程度词)+(身体部位)+(状态词)，如'肥厚熟靡'=肥厚+熟靡。",
      "vocabularyList": ["淫熟", "雌肉", "美肉", "靡情雌肉", "肥厚熟靡", "腻白乳肉", "舌下腺", "包皮缝", "尿垢"],
      "writingRules": ["组合公式：情感词（淫/靡）+身体（肉/乳/尻）+状态（熟/肥/厚）", "从解剖学借用术语（舌下腺），增加细腻感", "避免常见词，用'雌肉'替代'女人的肉'，用'熟靡'替代'软熟'"]
    }
  },
  "keyExcerpts": [
    "紧身修女服将她们除脸部外全都遮盖的严严实实，但犯规肉感的女体散发的雌性诱惑力，在这层薄薄衣衫的包裹中，仿佛一用力就可捏出其中淫靡肥润色欲爆表的雌肉。",
    "辛西娅那紧致包裹的修女服，被其他修女们帮助瞬间脱下，褐色长发盘头在脑后，修女服下只有几根皮带捆绑住身体。那皮带从爆乳的腻白乳肉下环绕而过，紧绷束缚在脖颈上项圈中，肥硕花白奶子，在黑色皮带的固定中，从腋下层层叠叠码在一堆。",
    "厚靡软舌不可能进入豆丁大小没有勃起的鸡鸡中，辛西娅含住特鲁鸡巴的口腔，舌头卷曲露出舌根底部的舌下腺，多年培养修炼口腔里分泌粘稠量大的唾液，从管口处喷射出两道水线。",
    "教皇大人，您最忠实的骚贱巨尻母猪，一定会让您得到最舒适巅峰的快乐！",
    "辛西娅那为服侍特鲁而锻炼出的绝世淫舌，对小鸡巴的没处动静一清二楚，鸡鸡颤抖射出液体，她知道特鲁教皇高潮了。"
  ]
